import re
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError

BUILTIN = {
    "max_size": None,
    "max_age": None,
    "naming": "numbered",
    "offset": 0,
    "compress_after": 1,
    "keep": 5,
    "keep_days": None,
}

_SIZE = re.compile(r"([0-9]+)([KkMmGg]?)\Z")
_DURATION = re.compile(r"([0-9]+)([mhd])\Z")
_OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
_NUMBER = re.compile(r"[0-9]+\Z")
_SIZE_UNITS = {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}
_MINUTES = {"m": 1, "h": 60, "d": 1440}


def _bad(message):
    raise DataError("policy", message)


def _size(value):
    if value == "off":
        return None
    match = _SIZE.match(value)
    if not match:
        _bad(f"bad size {value!r}")
    return int(match.group(1)) * _SIZE_UNITS[match.group(2).lower()]


def _duration(value):
    """Minutes, or None when off."""
    if value == "off":
        return None
    match = _DURATION.match(value)
    if not match:
        _bad(f"bad duration {value!r}")
    return int(match.group(1)) * _MINUTES[match.group(2)]


def _naming(value):
    if value not in ("numbered", "dated"):
        _bad(f"bad naming {value!r}")
    return value


def _offset(value):
    """Minutes east of UTC."""
    match = _OFFSET.match(value)
    if not match or int(match.group(2)) > 23 or int(match.group(3)) > 59:
        _bad(f"bad offset {value!r}")
    minutes = int(match.group(2)) * 60 + int(match.group(3))
    return -minutes if match.group(1) == "-" else minutes


def _count(minimum):
    def parse(value):
        if not _NUMBER.match(value) or int(value) < minimum:
            _bad(f"bad number {value!r}")
        return int(value)

    return parse


def _keep_days(value):
    return None if value == "off" else _count(1)(value)


PARSERS = {
    "max_size": _size,
    "max_age": _duration,
    "naming": _naming,
    "offset": _offset,
    "compress_after": _count(0),
    "keep": _count(1),
    "keep_days": _keep_days,
}


def load(path: Path):
    """Returns (defaults, {stream name: settings given in its own section})."""
    if not path.exists():
        return {}, {}
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        _bad(f"{path.name}: {e}")
    defaults = None
    sections = {}
    current = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                _bad(f"bad section line {line!r}")
            title = line[1:-1]
            if title == "defaults":
                if defaults is not None:
                    _bad("section defaults twice")
                defaults = current = {}
            elif title.startswith("stream ") and streams.valid(title[7:]):
                name = title[7:]
                if name in sections:
                    _bad(f"section {name} twice")
                sections[name] = current = {}
            else:
                _bad(f"unknown section {title!r}")
            continue
        if current is None or "=" not in line:
            _bad(f"bad line {line!r}")
        key, value = (part.strip() for part in line.split("=", 1))
        if key not in PARSERS:
            _bad(f"unknown key {key!r}")
        if key in current:
            _bad(f"key {key} twice")
        current[key] = PARSERS[key](value)
    return defaults or {}, sections


def settings(policy, name):
    defaults, sections = policy
    out = dict(BUILTIN)
    out.update(defaults)
    out.update(sections.get(name, {}))
    return out
