"""rotate (docs/rotate.md)."""

import gzip
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import policy as policy_mod
from logkeep import state as state_mod
from logkeep import streams
from logkeep.errors import DataError, Refused

_NUMBERED = re.compile(r"([1-9][0-9]*)(\.gz)?\Z")
_DATED = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([1-9][0-9]*))?(\.gz)?\Z")
_TIME = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})\Z")
_OLD_TIME = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\Z")


def _aware(text):
    if not _TIME.match(text):
        return None
    try:
        return datetime.fromisoformat(text)
    except ValueError:
        return None


def parse_state_time(value):
    if not isinstance(value, str):
        return None
    if _OLD_TIME.match(value):
        try:
            return datetime.fromisoformat(value).replace(tzinfo=timezone.utc)
        except ValueError:
            return None
    return _aware(value)


def _stamp(moment):
    return moment.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _validate_entry(name, entry):
    if "opened" in entry and parse_state_time(entry["opened"]) is None:
        raise DataError("state", f"{name}: bad opened")
    if "archives" in entry:
        archives = entry["archives"]
        if not isinstance(archives, dict):
            raise DataError("state", f"{name}: archives is not an object")
        for value in archives.values():
            if parse_state_time(value) is None:
                raise DataError("state", f"{name}: bad archive time")
    if "rotations" in entry:
        rotations = entry["rotations"]
        if isinstance(rotations, bool) or not isinstance(rotations, int) or rotations < 0:
            raise DataError("state", f"{name}: bad rotations")


def _day(text):
    try:
        date.fromisoformat(text)
    except ValueError:
        return None
    return text


def find_archives(data, name, naming):
    """List of dicts {file, key, compressed, day, k}; raises DataError on same-place files."""
    directory = streams.logs_dir(data)
    prefix = f"{name}.log."
    found = {}
    if directory.is_dir():
        for path in directory.iterdir():
            if not path.is_file() or not path.name.startswith(prefix):
                continue
            rest = path.name[len(prefix):]
            if naming == "numbered":
                match = _NUMBERED.match(rest)
                if not match:
                    continue
                key = (int(match.group(1)),)
                item = {"key": key, "compressed": bool(match.group(2)), "day": None, "k": None}
            else:
                match = _DATED.match(rest)
                if not match or _day(match.group(1)) is None:
                    continue
                k = int(match.group(2)) if match.group(2) else 1
                if match.group(2) and k < 2:
                    continue
                item = {"key": (match.group(1), k), "compressed": bool(match.group(3)),
                        "day": match.group(1), "k": k}
            item["file"] = path.name
            if item["key"] in found:
                raise DataError("archives", f"{name}: two archives in the same place: {item['key']}")
            found[item["key"]] = item
    return found


def _archive_name(name, naming, item, compressed):
    if naming == "numbered":
        base = f"{name}.log.{item['position']}"
    else:
        base = f"{name}.log.{item['day']}" + (f".{item['k']}" if item["k"] > 1 else "")
    return base + (".gz" if compressed else "")


def _first_line_time(path):
    with path.open("rb") as f:
        line = f.readline()
    text = line.decode("utf-8", errors="replace").rstrip("\r\n")
    return _aware(text.split(" ", 1)[0])


def run(ctx, names, dry_run, force):
    policy = policy_mod.load(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(ctx.data)) | set(policy[1])
    for name in existing:
        if name in doc["streams"]:
            _validate_entry(name, doc["streams"][name])
    if names:
        for name in names:
            if name not in existing:
                raise Refused("unknown-stream", f"no stream {name}")
        selected = sorted(set(names))
    else:
        selected = sorted(existing)
    plans = []
    for name in selected:
        settings = policy_mod.settings(policy, name)
        plans.append((name, settings, find_archives(ctx.data, name, settings["naming"])))

    now = ctx.now
    out = []
    totals = [0, 0, 0]
    operations = []
    new_streams = {}
    for name, settings, found in plans:
        entry = doc["streams"].get(name, {})
        log = streams.log_path(ctx.data, name)
        naming = settings["naming"]
        reason = None
        if not log.is_file():
            what = "no log"
        elif log.stat().st_size == 0:
            what = "empty"
        else:
            if force:
                reason = "forced"
            elif settings["max_size"] is not None and log.stat().st_size >= settings["max_size"]:
                reason = "size"
            elif settings["max_age"] is not None:
                if "opened" in entry:
                    opened = parse_state_time(entry["opened"])
                else:
                    opened = _first_line_time(log)
                if opened is not None and now - opened >= timedelta(minutes=settings["max_age"]):
                    reason = "age"
            what = f"rotate ({reason})" if reason else "not due"
        out.append(f"{name}: {what}")

        times = {}
        for key, value in (entry.get("archives") or {}).items():
            times[key] = value
        items = sorted(found.values(), key=lambda item: item["key"])
        for item in items:
            item["old"] = item["file"]
            item["time"] = times.get(item["file"])
            item["new"] = False
        if reason:
            if naming == "numbered":
                new_item = {"key": (0,), "compressed": False, "day": None, "k": None}
            else:
                local = now.astimezone(timezone(timedelta(minutes=settings["offset"])))
                day = local.date().isoformat()
                same = [item["k"] for item in items if item["day"] == day]
                k = max(same) + 1 if same else 1
                new_item = {"key": (day, k), "compressed": False, "day": day, "k": k}
            new_item.update(old=None, time=_stamp(now), new=True)
            items.append(new_item)
            items.sort(key=lambda item: item["key"])
            totals[0] += 1
        if naming == "numbered":
            items.sort(key=lambda item: item["key"])
        newest_first = items if naming == "numbered" else items[::-1]
        for position, item in enumerate(newest_first, 1):
            item["position"] = position
        if reason:
            new_item["old_name"] = _archive_name(name, naming, new_item, False)
        removed = []
        kept = []
        for item in newest_first:
            drop = item["position"] > settings["keep"]
            if not drop and settings["keep_days"] is not None and item["time"] is not None:
                moment = parse_state_time(item["time"])
                drop = now - moment >= timedelta(days=settings["keep_days"])
            (removed if drop else kept).append(item)
        compressed_count = 0
        lines = []
        archives_state = {}
        for index, item in enumerate(kept, 1):
            item["position"] = index
            compress = (not item["compressed"]) and index > settings["compress_after"]
            item["final_compressed"] = item["compressed"] or compress
            item["final"] = _archive_name(name, naming, item, item["final_compressed"])
            if compress:
                compressed_count += 1
            if item["new"]:
                lines.append(f"  new {item['final']}")
            elif item["final"] != item["old"]:
                lines.append(f"  {item['final']} <- {item['old']}")
            else:
                lines.append(f"  {item['final']}")
            if item["time"] is not None:
                archives_state[item["final"]] = item["time"]
        out.extend(lines)
        for item in removed:
            out.append(f"  remove {item['old'] or item['old_name']}")
        totals[1] += len(removed)
        totals[2] += compressed_count

        new_entry = {}
        if reason:
            new_entry["opened"] = ctx.stamp
        elif "opened" in entry:
            new_entry["opened"] = entry["opened"]
        new_entry["rotations"] = (entry.get("rotations") or 0) + (1 if reason else 0)
        new_entry["archives"] = archives_state
        new_streams[name] = new_entry
        operations.append((name, log, bool(reason), kept, removed))

    out.append(f"{totals[0]} rotated, {totals[1]} removed, {totals[2]} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    directory = streams.logs_dir(ctx.data)
    for name, log, rotated, kept, removed in operations:
        contents = {}
        for item in kept:
            if item["new"]:
                data = log.read_bytes()
            elif item["final"] != item["old"]:
                data = (directory / item["old"]).read_bytes()
            else:
                continue
            if item["final_compressed"] and not item["compressed"]:
                data = gzip.compress(data, mtime=0)
            contents[item["final"]] = data
        for item in removed:
            if item["old"]:
                (directory / item["old"]).unlink()
        for item in kept:
            if not item["new"] and item["final"] != item["old"]:
                (directory / item["old"]).unlink()
        for file_name, data in contents.items():
            (directory / file_name).write_bytes(data)
        if rotated:
            log.write_bytes(b"")
    doc["streams"].update(new_streams)
    state_mod.save(ctx.state_path, doc)
    return out
